#!/usr/bin/env python3
"""Build the local research reader from Markdown and JSON; no network access."""
from pathlib import Path
import json, html, os, re
import markdown
P = Path(__file__).resolve().parent
RD = sorted(d for d in P.iterdir() if d.is_dir() and re.fullmatch(r'\d{4}-\d{2}-\d{2}', d.name))[-1]   # đợt mới nhất
channels = json.loads((RD/'channels.json').read_text())
observations = json.loads((RD/'observations.json').read_text())
def md(path):
    return markdown.markdown(path.read_text(),extensions=['tables','toc','fenced_code'])
report=md(RD/'REPORT.md')
report=re.sub(r'href="(?!https?://|#)([^"]+)"',lambda m:'href="%s"'%os.path.normpath(f'{RD.name}/{m.group(1)}'),report)   # link trong báo cáo tính từ thư mục đợt
protocol=md(P/'METHOD.md')
protocol=re.sub(r'href="(?!https?://|#)([^"]+)"',r'href="\1"',protocol)
protocol=re.sub(r'id="([^"]+)"',r'id="protocol-\1"',protocol)
def wrap_tables(text): return text.replace('<table>','<div class="table-wrap" tabindex="0"><table>').replace('</table>','</table></div>')
langs=sorted({r['language'] for r in channels})
options=''.join(f'<option>{html.escape(x)}</option>' for x in langs)
payload=json.dumps({'channels':channels,'observations':observations},ensure_ascii=False).replace('</','<\\/')
template='''<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Nghiên cứu thị trường · Kênh lịch sử</title>
<style>
:root{color-scheme:light;--paper:#f6f3eb;--ink:#142b35;--muted:#526771;--line:#d6ddd7;--accent:#116b62;--card:#fffefa}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.75 system-ui,-apple-system,sans-serif}a{color:var(--accent);text-underline-offset:3px}a:hover{color:#07443d}header{padding:56px max(24px,calc((100vw - 1180px)/2)) 40px;background:var(--ink);color:white}header .eyebrow{font-size:12px;letter-spacing:.15em;text-transform:uppercase;color:#a8d9cb}header h1{font:500 clamp(30px,4vw,52px)/1.18 Georgia,serif;max-width:850px;margin:18px 0}header p{max-width:780px;color:#dae5e5}.stamp{display:inline-block;border:1px solid #759f99;border-radius:5px;padding:6px 12px;font-size:13px;color:#d5ebe5}.stats{display:flex;gap:36px;margin-top:30px;flex-wrap:wrap}.stats strong{font-size:29px;font-weight:600;display:block}.stats span{font-size:13px;color:#bcd2d4}nav{position:sticky;top:0;z-index:5;background:#fffefaf2;border-bottom:1px solid var(--line);display:flex;justify-content:center;gap:8px;padding:12px 18px;flex-wrap:wrap;backdrop-filter:blur(10px)}nav a{font-size:14px;text-decoration:none;padding:5px 12px;border-radius:4px}nav a:hover{background:#e7f0e8}main{max-width:1228px;margin:auto;padding:32px 24px 64px}section{margin-bottom:48px}.intro{background:#e7efe7;padding:20px 24px;border-left:4px solid var(--accent);max-width:100%}.intro p{margin:0}.reading{max-width:100%;background:var(--card);padding:34px 42px;border:1px solid var(--line);border-radius:8px}.reading h1{font-size:29px;line-height:1.3}.reading h2{font:600 25px/1.35 Georgia,serif;margin:40px 0 16px}.reading h3{font-size:19px;margin:32px 0 12px}.reading p,.reading li{max-width:970px}.reading li{margin:8px 0}.reading table{font-size:14px}.reading blockquote{margin:20px 0;border-left:3px solid var(--accent);padding:2px 20px;color:var(--muted)}h2{font-size:26px;line-height:1.35}.sub{color:var(--muted);margin-top:-8px}.filters{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.filters label{font-size:13px;font-weight:600;display:flex;flex-direction:column;gap:5px}.filters input,.filters select{font:inherit;font-size:15px;padding:11px 12px;min-height:45px;border:1px solid #a6b7b5;background:white;border-radius:5px;color:var(--ink)}.filters input{width:280px;max-width:100%}.table-wrap{overflow:auto;width:100%;border:1px solid var(--line);border-radius:5px;margin:20px 0;background:var(--card)}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.55}th{text-align:left;background:#e9eeea;color:#284a4b;font-weight:600}td,th{padding:13px 16px;border-bottom:1px solid var(--line);vertical-align:top;min-width:125px}td:first-child{min-width:180px;font-weight:600}td small{display:block;font-weight:400;font-size:12px;color:var(--muted);margin-top:7px}tr:last-child td{border-bottom:0}tbody tr:hover{background:#f3f7f0}.tag{font-size:12px;display:inline-block;border:1px solid #c4d4cd;border-radius:4px;padding:3px 6px;background:#f0f5ef}details{background:var(--card);border:1px solid var(--line);border-radius:8px}summary{cursor:pointer;padding:20px 24px;font-weight:600}details .reading{border:0;border-top:1px solid var(--line)}.downloads{display:flex;gap:18px;flex-wrap:wrap;font-size:14px}footer{font-size:13px;color:var(--muted);border-top:1px solid var(--line);padding-top:24px}button,a,input,select,summary{touch-action:manipulation}:focus-visible{outline:3px solid #c78620;outline-offset:3px}#count{font-size:13px;color:var(--muted)}.empty{text-align:center;padding:30px} @media(max-width:700px){body{font-size:15px}header{padding:32px 20px}.stats{gap:24px}main{padding:22px 14px 40px}.reading{padding:20px 18px}.reading h1{font-size:25px}.reading h2{font-size:23px}nav{gap:0;padding:8px 4px}nav a{font-size:12px;padding:5px 8px}.filters label{width:100%}.filters input,.filters select{width:100%}td,th{padding:12px}.intro{padding:16px}.stats strong{font-size:25px}}@media print{nav,.filters{display:none}header{background:white;color:black;padding:0}header p,header .eyebrow,.stats span{color:#333}.stamp{color:#333}.reading{padding:0;border:0}main{padding:0}.table-wrap{overflow:visible}table{font-size:10px}td,th{min-width:0;padding:6px}section{break-before:auto}a{color:inherit}.stats{margin-bottom:25px}}
</style></head><body>
<header><div class="eyebrow">Kênh lịch sử / nghiên cứu lựa chọn / 28.10.2026</div><h1>Lựa chọn quan trọng<br>hơn nỗ lực.</h1><p>Tìm câu chuyện có nhu cầu, có cửa cạnh tranh và hợp DNA kênh — trước khi đầu tư vào kịch bản và sản xuất.</p><div class="stamp">Giai đoạn 1 · Chưa có chủ đề được duyệt</div><div class="stats"><div><strong>31</strong><span>kênh trong danh mục</span></div><div><strong>11</strong><span>ngôn ngữ khảo sát</span></div><div><strong>16</strong><span>mẫu video có số liệu</span></div></div></header>
<nav aria-label="Mục lục"><a href="#report">Nhận định & ứng viên</a><a href="#channels">Danh mục kênh</a><a href="#videos">Bằng chứng video</a><a href="#protocol">Tiêu chí & quy trình</a></nav>
<main><section class="intro"><p><strong>Cách đọc:</strong> các con số là snapshot từ nhiều nguồn, không phải dữ liệu trực tiếp cùng thời điểm. Danh mục kênh là bản đồ để nghiên cứu; không phải bảng xếp hạng viral. Dữ liệu thiếu được để trống, không thay bằng 0.</p></section>
<section id="report" aria-label="Báo cáo"><article class="reading">__REPORT__</article></section>
<section id="channels"><h2>31 kênh · Lọc để đối chiếu</h2><p class="sub">Cùng ngách và ngoài ngách chung nội dung; tuổi kênh và độ sâu bằng chứng được ghi riêng.</p><div class="filters"><label>Tìm kênh, chủ đề hoặc ghi chú<input id="search" type="search" placeholder="Iran, bản đồ, kênh mới…"></label><label>Ngôn ngữ<select id="language"><option value="">Tất cả ngôn ngữ</option>__OPTIONS__</select></label><label>Nhóm<select id="group"><option value="">Tất cả nhóm</option><option>Cùng ngách</option><option>Ngoài ngách / chung nội dung</option></select></label><label>Bằng chứng<select id="status"><option value="">Tất cả mức khảo sát</option><option>Có mẫu định lượng</option><option>Đầu mối cần kiểm</option><option>Tham chiếu phong cách</option></select></label></div><div id="count" role="status" aria-live="polite"></div><div class="table-wrap" tabindex="0"><table><thead><tr><th>Kênh / ngôn ngữ</th><th>Nhóm / tuổi kênh</th><th>Chủ đề / cách kể</th><th>Bằng chứng / giới hạn</th></tr></thead><tbody id="channel-rows"></tbody></table></div><div class="downloads"><a href="__RD__/channels.csv" download>Tải danh mục CSV</a><a href="__RD__/channels.json" download>Dữ liệu JSON</a></div></section>
<section id="videos"><h2>16 quan sát video có thể truy nguồn</h2><p class="sub">Ngày đọc: 28/10/2026. Chưa xem trọn các video; không có phép đo retention hay tốc độ view gần đây.</p><div class="table-wrap" tabindex="0"><table><thead><tr><th>ID / kênh</th><th>Nội dung</th><th>Ngày đăng / snapshot nguồn</th><th>Views</th><th>Giới hạn và nguồn</th></tr></thead><tbody id="video-rows"></tbody></table></div><div class="downloads"><a href="__RD__/observations.csv" download>Tải quan sát CSV</a><a href="__RD__/observations.json" download>Dữ liệu JSON</a></div></section>
<section id="protocol"><h2>Tiêu chí và quy trình dùng lâu dài</h2><p class="sub">Cơ hội và độ tin cậy là hai đánh giá riêng. Chỉ sang nghiên cứu triển khai sau khi người dùng duyệt chủ đề.</p><details><summary>Mở toàn bộ quy trình, cách đo và cửa duyệt</summary><article class="reading">__PROTOCOL__</article></details></section>
<footer><p>Tài liệu gốc: <a href="__RD__/REPORT.md">Báo cáo Markdown</a> · <a href="METHOD.md">Quy trình Markdown</a> · <a href="__RD__/PRELIM.md">Bản sơ bộ được giữ để đối chiếu</a></p><p>Đọc trên localhost · Không có tracking, không gửi dữ liệu tới dịch vụ ngoài. Liên kết nguồn chỉ mở khi bạn chọn.</p></footer></main>
<script id="research-data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('research-data').textContent);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;const a=(url,label)=>`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(label)}</a>`;
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();
function renderChannels(){const q=normalize(document.getElementById('search').value);const lang=document.getElementById('language').value;const group=document.getElementById('group').value;const status=document.getElementById('status').value;const rs=data.channels.filter(r=>(!lang||r.language===lang)&&(!group||r.group===group)&&(!status||r.evidence_status===status)&&normalize(Object.values(r).join(' ')).includes(q));document.getElementById('count').textContent=`Hiển thị ${rs.length} / ${data.channels.length} kênh`;document.getElementById('channel-rows').innerHTML=rs.map(r=>`<tr><td>${a(r.source_url,r.channel)}<small>${e(r.language)} · link tới nguồn khảo sát</small></td><td>${e(r.group)}<small>${e(r.age_status)}</small></td><td>${e(r.topics)}<small>${e(r.format)}</small></td><td><span class="tag">${e(r.evidence_status)}</span><small>${e(r.limits)}</small></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Không có kênh khớp bộ lọc. Hãy đổi từ khóa hoặc chọn tất cả.</td></tr>';}
['search','language','group','status'].forEach(id=>document.getElementById(id).addEventListener('input',renderChannels));renderChannels();
document.getElementById('video-rows').innerHTML=data.observations.map(r=>`<tr><td>${e(r.id)} · ${e(r.channel)}<small>${e(r.language)}</small></td><td>${r.video_url?a(r.video_url,r.title):e(r.title)}<small>${e(r.format)}</small></td><td>${e(r.published_date||'Ngày đăng chưa chốt')}<small>Snapshot: ${e(r.source_snapshot_date||'Nguồn không ghi rõ')}</small></td><td>${new Intl.NumberFormat('vi-VN').format(r.views)}</td><td>${e(r.limits)}<small>${a(r.source_url,'Mở nguồn số liệu')}</small></td></tr>`).join('');
</script></body></html>'''
for key,value in {'__REPORT__':wrap_tables(report),'__PROTOCOL__':wrap_tables(protocol),'__OPTIONS__':options,'__DATA__':payload,'__RD__':RD.name}.items(): template=template.replace(key,value)
(P/'index.html').write_text(template)
print('Built index.html:',len(template),'characters')
